 92	public class ApiHandlers {
 93	    private final Gson gson = new GsonBuilder().create();
 94	    private final RoomRepository roomRepo;
 95	    private final ReservationService reservationService;
 96	    private final ReservationRepository reservationRepo;
 97	    private final MessageRepository messageRepo;
 98	
 99	    public ApiHandlers(RoomRepository roomRepo, ReservationService reservationService,
100	                      ReservationRepository reservationRepo, MessageRepository messageRepo) {
101	        this.roomRepo = roomRepo;
102	        this.reservationService = reservationService;
103	        this.reservationRepo = reservationRepo;
104	        this.messageRepo = messageRepo;
105	    }
106	
107	    public void getRooms(Context ctx) {
108	        try {
109	            List<Room> rooms = roomRepo.findAll();
110	            ctx.json(rooms.stream().map(this::roomToJson).toList());
111	        } catch (Exception e) {
112	            ctx.status(500).json(error("INTERNAL_ERROR", e.getMessage()));
113	        }
114	    }
115	
116	    public void createReservation(Context ctx) {
117	        try {
118	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
119	
120	            if (!body.has("roomNumber") || !body.has("guestName") || !body.has("guestEmail")
121	                    || !body.has("guestCpf") || !body.has("checkIn") || !body.has("checkOut")
122	                    || !body.has("guests") || !body.has("ratePlan")) {
123	                ctx.status(400).json(error("INVALID_REQUEST", "Missing required fields"));
124	                return;
125	            }
126	
127	            int roomNumber = body.get("roomNumber").getAsInt();
128	            String guestName = body.get("guestName").getAsString();
129	            String guestEmail = body.get("guestEmail").getAsString();
130	            String guestCpf = body.get("guestCpf").getAsString();
131	            LocalDate checkIn = LocalDate.parse(body.get("checkIn").getAsString());
132	            LocalDate checkOut = LocalDate.parse(body.get("checkOut").getAsString());
133	            int guests = body.get("guests").getAsInt();
134	            RatePlan ratePlan = RatePlan.fromLabel(body.get("ratePlan").getAsString());
135	
136	            Reservation reservation = reservationService.createReservation(
137	                    roomNumber, guestName, guestEmail, guestCpf,
138	                    checkIn, checkOut, guests, ratePlan);
139	
140	            ctx.status(201).json(reservationToJson(reservation));
141	        } catch (ApiException e) {
142	            ctx.status(e.getStatusCode()).json(error(e.getErrorCode(), e.getMessage()));
143	        } catch (Exception e) {
144	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
145	        }
146	    }
147	
148	    public void getReservation(Context ctx) {
149	        try {
150	            long id = ctx.pathParamAsClass("id", Long.class).get();
151	            Optional<Reservation> reservation = reservationRepo.findById(id);
152	
153	            if (reservation.isEmpty()) {
154	                ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
155	            } else {
156	                ctx.json(reservationToJson(reservation.get()));
157	            }
158	        } catch (Exception e) {
159	            ctx.status(500).json(error("INTERNAL_ERROR", e.getMessage()));
160	        }
161	    }
162	
163	    public void confirmReservation(Context ctx) {
164	        try {
165	            long id = ctx.pathParamAsClass("id", Long.class).get();
166	            JsonObject body = gson.fromJson(ctx.body(), JsonObject.class);
167	
168	            if (!body.has("amountPaid")) {
169	                ctx.status(400).json(error("INVALID_REQUEST", "Missing amountPaid"));
170	                return;
171	            }
172	
173	            BigDecimal amountPaid = body.get("amountPaid").getAsBigDecimal();
174	            Reservation confirmed = reservationService.confirmReservation(id, amountPaid);
175	            ctx.json(reservationToJson(confirmed));
176	        } catch (ApiException e) {
177	            ctx.status(e.getStatusCode()).json(error(e.getErrorCode(), e.getMessage()));
178	        } catch (Exception e) {
179	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
180	        }
181	    }
182	
183	    public void cancelReservation(Context ctx) {
184	        try {
185	            long id = ctx.pathParamAsClass("id", Long.class).get();
186	            Reservation cancelled = reservationService.cancelReservation(id);
187	            ctx.json(reservationToJson(cancelled));
188	        } catch (ApiException e) {
189	            ctx.status(e.getStatusCode()).json(error(e.getErrorCode(), e.getMessage()));
190	        } catch (Exception e) {
191	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
192	        }
193	    }
194	
195	    public void checkIn(Context ctx) {
196	        try {
197	            long id = ctx.pathParamAsClass("id", Long.class).get();
198	            Reservation checkedIn = reservationService.checkIn(id);
199	            ctx.json(reservationToJson(checkedIn));
200	        } catch (ApiException e) {
201	            ctx.status(e.getStatusCode()).json(error(e.getErrorCode(), e.getMessage()));
202	        } catch (Exception e) {
203	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
204	        }
205	    }
206	
207	    public void checkOut(Context ctx) {
208	        try {
209	            long id = ctx.pathParamAsClass("id", Long.class).get();
210	            Reservation checkedOut = reservationService.checkOut(id);
211	            ctx.json(comprovanteToJson(reservationService.generateComprovante(checkedOut), checkedOut));
212	        } catch (ApiException e) {
213	            ctx.status(e.getStatusCode()).json(error(e.getErrorCode(), e.getMessage()));
214	        } catch (Exception e) {
215	            ctx.status(400).json(error("INTERNAL_ERROR", e.getMessage()));
216	        }
217	    }
218	
219	    public void getDocument(Context ctx) {
220	        try {
221	            long id = ctx.pathParamAsClass("id", Long.class).get();
222	            Optional<Reservation> reservation = reservationRepo.findById(id);
223	
224	            if (reservation.isEmpty()) {
225	                ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Reservation not found"));
226	                return;
227	            }
228	
229	            if (reservation.get().getAmountPaid().compareTo(BigDecimal.ZERO) <= 0) {
230	                ctx.status(404).json(error("RESERVATION_NOT_FOUND", "Document only available for paid reservations"));
231	                return;
232	            }
233	
234	            String comprovante = reservationService.generateComprovante(reservation.get());
235	            ctx.json(comprovanteToJson(comprovante, reservation.get()));
236	        } catch (Exception e) {
237	            ctx.status(500).json(error("INTERNAL_ERROR", e.getMessage()));
238	        }
239	    }
240	
241	    public void getMessages(Context ctx) {
242	        try {
243	            List<Message> messages = messageRepo.findAll();
244	            ctx.json(messages.stream().map(this::messageToJson).toList());
245	        } catch (Exception e) {
246	            ctx.status(500).json(error("INTERNAL_ERROR", e.getMessage()));
247	        }
248	    }
249	
250	    public void getOccupancyReport(Context ctx) {
251	        try {
252	            String dateStr = ctx.queryParam("date");
253	            if (dateStr == null || dateStr.isEmpty()) {
254	                ctx.status(400).json(error("INVALID_REQUEST", "Missing date parameter"));
255	                return;
256	            }
257	
258	            LocalDate date = LocalDate.parse(dateStr);
259	            OccupancyReport report = new OccupancyReport(roomRepo, reservationRepo, date);
260	            ctx.contentType("text/csv; charset=utf-8").result(report.generate());
261	        } catch (Exception e) {
262	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
263	        }
264	    }
265	
266	    public void getRevenueReport(Context ctx) {
267	        try {
268	            String monthStr = ctx.queryParam("month");
269	            if (monthStr == null || monthStr.isEmpty()) {
270	                ctx.status(400).json(error("INVALID_REQUEST", "Missing month parameter"));
271	                return;
272	            }
273	
274	            YearMonth ym = YearMonth.parse(monthStr);
275	            RevenueReport report = new RevenueReport(reservationRepo, ym.getMonthValue(), ym.getYear());
276	            ctx.contentType("text/csv; charset=utf-8").result(report.generate());
277	        } catch (Exception e) {
278	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
279	        }
280	    }
281	
282	    public void getTourismTaxReport(Context ctx) {
283	        try {
284	            String monthStr = ctx.queryParam("month");
285	            if (monthStr == null || monthStr.isEmpty()) {
286	                ctx.status(400).json(error("INVALID_REQUEST", "Missing month parameter"));
287	                return;
288	            }
289	
290	            YearMonth ym = YearMonth.parse(monthStr);
291	            TourismTaxReport report = new TourismTaxReport(reservationRepo, ym.getMonthValue(), ym.getYear());
292	            ctx.contentType("text/csv; charset=utf-8").result(report.generate());
293	        } catch (Exception e) {
294	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
295	        }
296	    }
297	
298	    public void getRatePlanReport(Context ctx) {
299	        try {
300	            String monthStr = ctx.queryParam("month");
301	            if (monthStr == null || monthStr.isEmpty()) {
302	                ctx.status(400).json(error("INVALID_REQUEST", "Missing month parameter"));
303	                return;
304	            }
305	
306	            YearMonth ym = YearMonth.parse(monthStr);
307	            RatePlanReport report = new RatePlanReport(reservationRepo, ym.getMonthValue(), ym.getYear());
308	            ctx.contentType("text/csv; charset=utf-8").result(report.generate());
309	        } catch (Exception e) {
310	            ctx.status(400).json(error("INVALID_REQUEST", e.getMessage()));
311	        }
312	    }
313	
314	    private JsonObject roomToJson(Room room) {
315	        JsonObject obj = new JsonObject();
316	        obj.addProperty("number", room.getNumber());
317	        obj.addProperty("type", room.getType().getLabel());
318	        obj.addProperty("capacity", room.getCapacity());
319	        obj.addProperty("nightlyRate", Double.parseDouble(String.format("%.2f", room.getNightlyRate())));
320	        return obj;
321	    }
322	
323	    private JsonObject reservationToJson(Reservation res) {
324	        JsonObject obj = new JsonObject();
325	        obj.addProperty("id", res.getId());
326	        obj.addProperty("roomNumber", res.getRoomNumber());
327	        obj.addProperty("guestName", res.getGuestName());
328	        obj.addProperty("guestEmail", res.getGuestEmail());
329	        obj.addProperty("guestCpf", res.getGuestCpf());
330	        obj.addProperty("checkIn", res.getCheckIn().toString());
331	        obj.addProperty("checkOut", res.getCheckOut().toString());
332	        obj.addProperty("guests", res.getGuests());
333	        obj.addProperty("ratePlan", res.getRatePlan().getLabel());
334	        obj.addProperty("nights", res.getNights());
335	        obj.addProperty("subtotal", Double.parseDouble(String.format("%.2f", res.getSubtotal())));
336	        obj.addProperty("discount", Double.parseDouble(String.format("%.2f", res.getDiscount())));
337	        obj.addProperty("total", Double.parseDouble(String.format("%.2f", res.getTotal())));
338	        obj.addProperty("status", res.getStatus().getLabel());
339	        obj.addProperty("amountPaid", Double.parseDouble(String.format("%.2f", res.getAmountPaid())));
340	        if (res.getRefund() != null) {
341	            obj.addProperty("refund", Double.parseDouble(String.format("%.2f", res.getRefund())));
342	        } else {
343	            obj.addProperty("refund", (Number) null);
344	        }
345	        return obj;
346	    }
347	
348	    private JsonObject messageToJson(Message msg) {
349	        JsonObject obj = new JsonObject();
350	        obj.addProperty("id", msg.getId());
351	        obj.addProperty("channel", msg.getChannel());
352	        obj.addProperty("to", msg.getTo());
353	        obj.addProperty("subject", msg.getSubject());
354	        obj.addProperty("body", msg.getBody());
355	        return obj;
356	    }
357	
358	    private JsonObject comprovanteToJson(String comprovante, Reservation res) {
359	        JsonObject obj = new JsonObject();
360	        obj.addProperty("title", "Comprovante de reserva");
361	        obj.addProperty("reservationId", res.getId());
362	        obj.addProperty("guestName", res.getGuestName());
363	        obj.addProperty("guestCpf", res.getGuestCpf());
364	        obj.addProperty("roomNumber", res.getRoomNumber());
365	        try {
366	            Optional<Room> room = roomRepo.findByNumber(res.getRoomNumber());
367	            obj.addProperty("roomType", room.isPresent() ? room.get().getType().getLabel() : "");
368	        } catch (Exception ignored) {
369	        }
370	        obj.addProperty("checkIn", res.getCheckIn().toString());
371	        obj.addProperty("checkOut", res.getCheckOut().toString());
372	        obj.addProperty("nights", res.getNights());
373	        obj.addProperty("subtotal", Double.parseDouble(String.format("%.2f", res.getSubtotal())));
374	        obj.addProperty("discount", Double.parseDouble(String.format("%.2f", res.getDiscount())));
375	        obj.addProperty("total", Double.parseDouble(String.format("%.2f", res.getTotal())));
376	        return obj;
377	    }
378	
379	    private JsonObject error(String code, String message) {
380	        JsonObject obj = new JsonObject();
381	        obj.addProperty("error", code);
382	        obj.addProperty("message", message);
383	        return obj;
384	    }
385	}

