  1	package com.pousada.business;
  2	
  3	import com.pousada.db.*;
  4	import com.pousada.models.*;
  5	import com.pousada.utils.PricingUtils;
  6	
  7	import java.math.BigDecimal;
  8	import java.time.LocalDate;
  9	import java.util.List;
 10	import java.util.Optional;
 11	
 12	public class ReservationService {
 13	    private final ReservationRepository reservationRepo;
 14	    private final RoomRepository roomRepo;
 15	    private final MessageRepository messageRepo;
 16	
 17	    public ReservationService(ReservationRepository reservationRepo, RoomRepository roomRepo, MessageRepository messageRepo) {
 18	        this.reservationRepo = reservationRepo;
 19	        this.roomRepo = roomRepo;
 20	        this.messageRepo = messageRepo;
 21	    }
 22	
 23	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 24	                                        LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan) throws Exception {
 25	        Optional<Room> room = roomRepo.findByNumber(roomNumber);
 26	        if (room.isEmpty()) {
 27	            throw new ApiException(404, "ROOM_NOT_FOUND", "Room not found");
 28	        }
 29	
 30	        if (guests < 1) {
 31	            throw new ApiException(400, "INVALID_REQUEST", "At least one guest is required");
 32	        }
 33	
 34	        if (guests > room.get().getCapacity()) {
 35	            throw new ApiException(422, "CAPACITY_EXCEEDED", "Too many guests for this room");
 36	        }
 37	
 38	        if (!checkOut.isAfter(checkIn)) {
 39	            throw new ApiException(400, "INVALID_REQUEST", "Check-out must be after check-in");
 40	        }
 41	
 42	        List<Reservation> conflicts = reservationRepo.findByRoomAndDateRange(roomNumber, checkIn, checkOut);
 43	        if (!conflicts.isEmpty()) {
 44	            throw new ApiException(409, "ROOM_UNAVAILABLE", "Room is not available for these dates");
 45	        }
 46	
 47	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
 48	        BigDecimal[] nightlyPrices = new BigDecimal[nights];
 49	        for (int i = 0; i < nights; i++) {
 50	            LocalDate night = checkIn.plusDays(i);
 51	            nightlyPrices[i] = PricingUtils.calculateNightlyPrice(room.get().getNightlyRate(), night);
 52	        }
 53	
 54	        BigDecimal subtotal = PricingUtils.calculateSubtotal(nightlyPrices);
 55	        BigDecimal discount = PricingUtils.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
 56	        BigDecimal total = PricingUtils.calculateTotal(subtotal, discount);
 57	
 58	        return reservationRepo.create(roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut,
 59	                guests, ratePlan, nights, subtotal, discount, total);
 60	    }
 61	
 62	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws Exception {
 63	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
 64	        if (reservation.isEmpty()) {
 65	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
 66	        }
 67	
 68	        Reservation res = reservation.get();
 69	        if (res.getStatus() != ReservationStatus.PENDING) {
 70	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot confirm a reservation that is not pending");
 71	        }
 72	
 73	        Reservation confirmed = res.withStatus(ReservationStatus.CONFIRMED)
 74	                .withAmountPaid(amountPaid);
 75	        reservationRepo.update(confirmed);
 76	
 77	        sendConfirmationEmail(confirmed);
 78	
 79	        return confirmed;
 80	    }
 81	
 82	    public Reservation cancelReservation(long reservationId) throws Exception {
 83	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
 84	        if (reservation.isEmpty()) {
 85	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
 86	        }
 87	
 88	        Reservation res = reservation.get();
 89	        if (res.getStatus() == ReservationStatus.CHECKED_OUT || res.getStatus() == ReservationStatus.CANCELLED) {
 90	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot cancel a reservation in this state");
 91	        }
 92	
 93	        if (res.getStatus() == ReservationStatus.CHECKED_IN) {
 94	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot cancel a checked-in reservation");
 95	        }
 96	
 97	        BigDecimal refund = BigDecimal.ZERO;
 98	        if (res.getStatus() == ReservationStatus.CONFIRMED && res.getRatePlan() == RatePlan.STANDARD) {
 99	            refund = res.getAmountPaid();
100	        }
101	
102	        Reservation cancelled = res.withStatus(ReservationStatus.CANCELLED)
103	                .withRefund(refund);
104	        reservationRepo.update(cancelled);
105	
106	        return cancelled;
107	    }
108	
109	    public Reservation checkIn(long reservationId) throws Exception {
110	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
111	        if (reservation.isEmpty()) {
112	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
113	        }
114	
115	        Reservation res = reservation.get();
116	        if (res.getStatus() != ReservationStatus.CONFIRMED) {
117	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot check-in a reservation that is not confirmed");
118	        }
119	
120	        Reservation checkedIn = res.withStatus(ReservationStatus.CHECKED_IN);
121	        reservationRepo.update(checkedIn);
122	
123	        return checkedIn;
124	    }
125	
126	    public Reservation checkOut(long reservationId) throws Exception {
127	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
128	        if (reservation.isEmpty()) {
129	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
130	        }
131	
132	        Reservation res = reservation.get();
133	        if (res.getStatus() != ReservationStatus.CHECKED_IN) {
134	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot check-out a reservation that is not checked-in");
135	        }
136	
137	        Reservation checkedOut = res.withStatus(ReservationStatus.CHECKED_OUT);
138	        reservationRepo.update(checkedOut);
139	
140	        return checkedOut;
141	    }
142	
143	    private void sendConfirmationEmail(Reservation reservation) throws Exception {
144	        String subject = "Reserva confirmada - Pousada Maré Alta";
145	        String comprovante = generateComprovante(reservation);
146	        String body = """
147	            Olá, %s!
148	
149	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
150	
151	            %s
152	
153	            A entrada é a partir das 14h, e a saída, até as 12h.
154	            Até breve!
155	            """.formatted(reservation.getGuestName(), comprovante);
156	
157	        messageRepo.create("EMAIL", reservation.getGuestEmail(), subject, body);
158	    }
159	
160	    public String generateComprovante(Reservation reservation) throws Exception {
161	        Optional<Room> room = roomRepo.findByNumber(reservation.getRoomNumber());
162	        if (room.isEmpty()) {
163	            throw new Exception("Room not found");
164	        }
165	
166	        String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
167	        String discountLine = reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0
168	                ? "Desconto: " + PricingUtils.formatCurrency(reservation.getDiscount()) + "\n"
169	                : "";
170	
171	        return String.format("""
172	                Comprovante de reserva nº %d
173	                Hóspede: %s (CPF %s)
174	                Quarto: %d (%s)
175	                Entrada: %s | Saída: %s | %s
176	                Diárias: %s
177	                %sTotal: %s""",
178	                reservation.getId(),
179	                reservation.getGuestName(),
180	                reservation.getGuestCpf(),
181	                reservation.getRoomNumber(),
182	                room.get().getType().getLabel(),
183	                PricingUtils.formatDate(reservation.getCheckIn()),
184	                PricingUtils.formatDate(reservation.getCheckOut()),
185	                nightsText,
186	                PricingUtils.formatCurrency(reservation.getSubtotal()),
187	                discountLine,
188	                PricingUtils.formatCurrency(reservation.getTotal())
189	        );
190	    }
191	}
