 62	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) throws Exception {
 63	        Optional<Reservation> reservation = reservationRepo.findById(reservationId);
 64	        if (reservation.isEmpty()) {
 65	            throw new ApiException(404, "RESERVATION_NOT_FOUND", "Reservation not found");
 66	        }
 67	
 68	        Reservation res = reservation.get();
 69	        if (res.getStatus() != ReservationStatus.PENDING) {
 70	            throw new ApiException(409, "OPERATION_NOT_ALLOWED", "Cannot confirm a reservation that is not pending");
 71	        }
 72	
 73	        Reservation confirmed = res.withStatus(ReservationStatus.CONFIRMED)
 74	                .withAmountPaid(amountPaid);
 75	        reservationRepo.update(confirmed);
 76	
 77	        sendConfirmationEmail(confirmed);
 78	
 79	        return confirmed;
