 21	package com.pousada.reports;
 22	
 23	import com.pousada.db.ReservationRepository;
 24	import com.pousada.db.RoomRepository;
 25	import com.pousada.models.Reservation;
 26	import com.pousada.models.ReservationStatus;
 27	import com.pousada.models.Room;
 28	import com.pousada.utils.PricingUtils;
 29	
 30	import java.sql.SQLException;
 31	import java.time.LocalDate;
 32	import java.util.*;
 33	
 34	public class OccupancyReport extends Report {
 35	    private final RoomRepository roomRepo;
 36	    private final ReservationRepository reservationRepo;
 37	    private final LocalDate date;
 38	
 39	    public OccupancyReport(RoomRepository roomRepo, ReservationRepository reservationRepo, LocalDate date) {
 40	        this.roomRepo = roomRepo;
 41	        this.reservationRepo = reservationRepo;
 42	        this.date = date;
 43	    }
 44	
 45	    @Override
 46	    public String generate() {
 47	        try {
 48	            StringBuilder sb = new StringBuilder();
 49	            String title = generateTitle("occupancy", PricingUtils.formatDateIso(date));
 50	            sb.append(title).append("\n");
 51	
 52	            sb.append(generateCsvRow("room", "type", "reservation", "check_in", "check_out")).append("\n");
 53	
 54	            List<Room> rooms = roomRepo.findAll();
 55	            int occupiedCount = 0;
 56	
 57	            for (Room room : rooms) {
 58	                LocalDate checkInDay = date;
 59	                LocalDate checkOutDay = date.plusDays(1);
 60	
 61	                List<Reservation> reservations = reservationRepo.findByRoomAndDateRange(
 62	                        room.getNumber(), checkInDay, checkOutDay);
 63	
 64	                boolean occupied = false;
 65	                for (Reservation res : reservations) {
 66	                    if (res.getStatus() == ReservationStatus.CONFIRMED
 67	                            || res.getStatus() == ReservationStatus.CHECKED_IN
 68	                            || res.getStatus() == ReservationStatus.CHECKED_OUT) {
 69	                        occupied = true;
 70	                        sb.append(generateCsvRow(
 71	                                String.valueOf(room.getNumber()),
 72	                                room.getType().getLabel(),
 73	                                String.valueOf(res.getId()),
 74	                                PricingUtils.formatDateIso(res.getCheckIn()),
 75	                                PricingUtils.formatDateIso(res.getCheckOut())
 76	                        )).append("\n");
 77	                        break;
 78	                    }
 79	                }
 80	
 81	                if (occupied) {
 82	                    occupiedCount++;
 83	                }
 84	            }
 85	
 86	            sb.append(generateCsvRow("total", String.valueOf(occupiedCount) + "/" + rooms.size())).append("\n");
 87	
 88	            return sb.toString();
 89	        } catch (SQLException e) {
 90	            throw new RuntimeException(e);
 91	        }
 92	    }
 93	}
