106	    private final int month;
107	    private final int year;
108	
109	    public RevenueReport(ReservationRepository reservationRepo, int month, int year) {
110	        this.reservationRepo = reservationRepo;
111	        this.month = month;
112	        this.year = year;
113	    }
114	
